from collections import Counter
cut_rows = [r for r in rows if r['finish']=='length']
fin_rows = [r for r in rows if r['finish']=='stop']
def line_openings(grp):
    c = Counter()
    for r in grp:
        for line in r['text'].split('\n'):
            line=line.strip()
            if line:
                c[line.split(' ')[0]] += 1
    tot = sum(len(r['text'].split()) for r in grp)
    return c, tot
cc, ctot = line_openings(cut_rows); fc, ftot = line_openings(fin_rows)
keys = set(cc) | set(fc)
diffs = []
for k in keys:
    if k in ('$','-','\\[','\\('): continue
    a = cc.get(k,0)/ctot*1000; b = fc.get(k,0)/ftot*1000
    if a > b + 0.15 and cc.get(k,0) > 20:
        diffs.append((a-b, k, a, b, cc.get(k,0)))
diffs.sort(reverse=True)
for d,k,a,b,n in diffs[:20]:
    print(f'{k:15s} cut {a:.3f} fin {b:.3f} n {n}')

